\begin{tikzpicture}[x=0.7cm,y=0.7cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{connectionRed}{HTML}{EF6068}
\definecolor{pointBlue}{HTML}{268CFF}
\draw[<->,line width=0.5pt] (-3.9,0)--(3.9,0) node[right] {$x$};
\draw[<->,line width=0.5pt] (0,-3.9)--(0,3.9) node[above] {$y$};
\foreach \v in {-3,-2,-1,1,2,3} {
\draw[line width=0.4pt] (\v,0.1)--(\v,-0.1);
\node[below] at (\v,-0.1) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};
\draw[line width=0.4pt] (0.1,\v)--(-0.1,\v);
\node[left] at (-0.1,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};
}
\coordinate (P) at (2,3);
\coordinate (A) at (3,-2);
\coordinate (B) at (-1,-1);
\coordinate (C) at (-3,3);
\draw[connectionRed,dashed,line width=0.4pt] (P)--(A);
\draw[connectionRed,dashed,line width=0.4pt] (P)--(B);
\draw[connectionRed,dashed,line width=0.4pt] (P)--(C);
\foreach \p in {P,A,B,C} {\fill[pointBlue] (\p) circle (2pt);}
\node[below right] at (A) {$A(3,-2)$};
\node[below left] at (B) {$B(-1,-1)$};
\node[below] at (C) {$C(-3,3)$};
\node[below] at (P) {$(2,3)$};
\end{tikzpicture}

